sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float rr;
uniform float rg;
uniform float rb;
uniform float gr;
uniform float gg;
uniform float gb;
uniform float br;
uniform float bg;
uniform float bb;
uniform float monochrome;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 o = float3(dot(s, float3(rr, rg, rb)), dot(s, float3(gr, gg, gb)), dot(s, float3(br, bg, bb)));
    if (monochrome > 0.5) o = float3(o.r);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
